# description:
# Identify the corner of a grid that does not contain a 3-pixel L-shape.
# Each L-shape is formed by two connected components of length 2 and 1, arranged in an L configuration.
# The task is to determine which of the four corners of the grid lacks this specific L-shape pattern.

def main(input_grid: np.ndarray) -> str:
    # Define L-shaped patterns for each corner
    L_shaped_patterns = {
        'top-left': [(0, 0), (0, 1), (1, 0)],
        'top-right': [(0, -1), (0, -2), (1, -1)],
        'bottom-left': [(-1, 0), (-1, 1), (-2, 0)],
        'bottom-right': [(-1, -1), (-1, -2), (-2, -1)]
    }

    # Check each corner for the presence of an L-shape
    grid_height, grid_width = input_grid.shape
    for corner, positions in L_shaped_patterns.items():
        if corner == 'top-left':
            if all(input_grid[x, y] != Color.BLACK for x, y in positions):
                continue
        elif corner == 'top-right':
            if all(input_grid[0, grid_width + y] != Color.BLACK for x, y in positions):
                continue
        elif corner == 'bottom-left':
            if all(input_grid[grid_height + x, y] != Color.BLACK for x, y in positions):
                continue
        elif corner == 'bottom-right':
            if all(input_grid[grid_height + x, grid_width + y] != Color.BLACK for x, y in positions):
                continue
        return corner  # Return the first corner without an L-shape

    return "All corners have L-shapes"  # Fallback just in case

def generate_input() -> np.ndarray:
    # Random grid size
    n, m = np.random.randint(5, 10), np.random.randint(5, 10)
    grid = np.zeros((n, m), dtype=int)

    # Choose a random color for L-shapes
    l_shape_color = np.random.choice(list(Color.NOT_BLACK))

    # Place L-shapes in three random corners
    corners = ['top-left', 'top-right', 'bottom-left', 'bottom-right']
    np.random.shuffle(corners)
    for corner in corners[:3]:
        if corner == 'top-left':
            grid[0, 0], grid[0, 1], grid[1, 0] = l_shape_color, l_shape_color, l_shape_color
        elif corner == 'top-right':
            grid[0, -1], grid[0, -2], grid[1, -1] = l_shape_color, l_shape_color, l_shape_color
        elif corner == 'bottom-left':
            grid[-1, 0], grid[-1, 1], grid[-2, 0] = l_shape_color, l_shape_color, l_shape_color
        elif corner == 'bottom-right':
            grid[-1, -1], grid[-1, -2], grid[-2, -1] = l_shape_color, l_shape_color, l_shape_color

    # Optionally scatter some other colors for distraction
    randomly_scatter_points(grid, color=np.random.choice(list(Color.NOT_BLACK)), density=0.1)

    return grid

from common import *

import numpy as np
from typing import *

# concepts:
# pattern_recognition, shape_identification, corner_detection

# description:
# Given a grid with three 3-pixel L-shapes occupying three corners, identify the unoccupied corner.

def main(input_grid):
    # Get all connected components that are not the background
    objects = find_connected_components(input_grid, background=Color.BLACK, connectivity=8, monochromatic=True)

    # Detect the corners with L-shapes
    corners_with_L = set()
    for obj in objects:
        # Get the bounding box of the object
        x, y, w, h = bounding_box(obj, background=Color.BLACK)

        # Check if the object is an L-shape
        if (w, h) == (2, 2):
            # Determine which corner this L-shape occupies
            if x == 0 and y == 0:
                corners_with_L.add("upper_left")
            elif x == 0 and y == input_grid.shape[1] - 2:
                corners_with_L.add("upper_right")
            elif x == input_grid.shape[0] - 2 and y == 0:
                corners_with_L.add("lower_left")
            elif x == input_grid.shape[0] - 2 and y == input_grid.shape[1] - 2:
                corners_with_L.add("lower_right")

    # Determine the unoccupied corner
    all_corners = {"upper_left", "upper_right", "lower_left", "lower_right"}
    unoccupied_corner = all_corners - corners_with_L

    return unoccupied_corner.pop()

def generate_input():
    # Create a blank grid
    grid_size = np.random.randint(5, 8)
    grid = np.zeros((grid_size, grid_size), dtype=int)

    # Randomly choose three corners to place L-shapes
    corners = ["upper_left", "upper_right", "lower_left", "lower_right"]
    occupied_corners = set(np.random.choice(corners, 3, replace=False))

    # Place L-shapes in the chosen corners
    for corner in occupied_corners:
        color = np.random.choice(list(Color.NOT_BLACK))
        if corner == "upper_left":
            grid[0, 0] = grid[0, 1] = grid[1, 0] = color
        elif corner == "upper_right":
            grid[0, -1] = grid[0, -2] = grid[1, -1] = color
        elif corner == "lower_left":
            grid[-1, 0] = grid[-1, 1] = grid[-2, 0] = color
        elif corner == "lower_right":
            grid[-1, -1] = grid[-1, -2] = grid[-2, -1] = color

    return grid
